// @generated by:gauntlet run:godseye-local-backend
import { randomUUID } from "node:crypto";
import {
  BackendConfiguration,
  BackendConfigurationView,
  CONTROL_API_HEADER,
  CONTROL_API_VERSION,
  type ConfigureBackendInput,
  ProjectResponse,
} from "@godseye/contracts";
import { applicationLifecycleGuard } from "@godseye/core";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createControlClient } from "../packages/control-client/src/index.js";
import { projectInput } from "./helpers.js";
import { type OwnerAuthFixture, ownerAuthFixture } from "./owner-auth-fixture.js";
import { databaseFixture } from "./pg-helpers.js";

const configuration = {
  enabled: true,
  registrationEnabled: true,
  allowedOrigins: ["http://localhost:4731"],
  maxFileMiB: 8,
  storageMiB: 32,
  maxFiles: 10,
  eventRetention: 100,
};

describe("owner application-backend configuration and runtime lifecycle", () => {
  let fixture: OwnerAuthFixture;
  let headers: Headers;
  beforeEach(async () => {
    fixture = await ownerAuthFixture();
    headers = (await fixture.session()).headers;
    headers.set(CONTROL_API_HEADER, CONTROL_API_VERSION);
  });
  afterEach(async () => fixture.close());
  function request(path: string, method = "GET", body?: unknown, key = randomUUID()) {
    const selected = new Headers(headers);
    if (method !== "GET") selected.set("idempotency-key", key);
    return fixture.app.request(new URL(`/api/v1${path}`, fixture.origin), {
      method,
      headers: selected,
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
    });
  }
  async function project(slug = projectInput.slug) {
    const response = await request("/projects", "POST", { ...projectInput, slug });
    expect(response.status).toBe(201);
    const result = ProjectResponse.parse(await response.json());
    const environment = result.environments[0];
    if (!environment) throw new Error("Application backend fixture missing environment");
    const path = `/projects/${result.id}/environments/${environment.id}/backend`;
    const input: ConfigureBackendInput = {
      expectedRevision: 0,
      expectedProjectRevision: result.revision,
      expectedEnvironmentRevision: environment.revision,
      configuration,
    };
    return { project: result, environment, path, input };
  }

  it("T-AC-61 authenticates backend reads and writes before parsing their body", async () => {
    const selected = await project();
    for (const method of ["GET", "PUT"]) {
      const response = await fixture.app.request(
        new URL(`/api/v1${selected.path}`, fixture.origin),
        {
          method,
          headers: fixture.headers(),
          ...(method === "PUT" ? { body: "{" } : {}),
        },
      );
      expect(response.status).toBe(401);
    }
  });

  it("T-AC-61 distinguishes absent configuration from a locally prepared runtime", async () => {
    const selected = await project();
    const initial = await request(selected.path);
    expect(initial.status).toBe(200);
    expect(BackendConfigurationView.parse(await initial.json())).toMatchObject({
      projectId: selected.project.id,
      environmentId: selected.environment.id,
      revision: 0,
      configuration: null,
      state: "unconfigured",
      runtimeConnected: false,
    });
    const configured = await request(selected.path, "PUT", selected.input);
    expect(configured.status).toBe(200);
    expect(BackendConfigurationView.parse(await configured.json())).toMatchObject({
      revision: 1,
      configuration,
      state: "prepared",
      runtimeConnected: false,
    });
  });

  it("T-AC-61 requires recent owner passkey confirmation for configuration", async () => {
    const selected = await project();
    headers = (await fixture.session(6 * 60_000)).headers;
    const response = await request(selected.path, "PUT", selected.input);
    expect(response.status).toBe(403);
    expect(await response.json()).toMatchObject({ error: { code: "STEP_UP_REQUIRED" } });
    expect(
      BackendConfigurationView.parse(await (await request(selected.path)).json()).revision,
    ).toBe(0);
  });

  it("T-AC-61 replays the same configuration once and rejects changed idempotency payload", async () => {
    const selected = await project();
    const key = randomUUID();
    const first = await request(selected.path, "PUT", selected.input, key);
    const replay = await request(selected.path, "PUT", selected.input, key);
    expect(first.status).toBe(200);
    expect(replay.status).toBe(200);
    expect(await replay.json()).toEqual(await first.json());
    const changed = await request(
      selected.path,
      "PUT",
      { ...selected.input, configuration: { ...configuration, enabled: false } },
      key,
    );
    expect(changed.status).toBe(409);
    expect(await changed.json()).toMatchObject({ error: { code: "IDEMPOTENCY_CONFLICT" } });
  });

  it("T-AC-61 admits one winner for competing configuration revisions", async () => {
    const selected = await project();
    const results = await Promise.all([
      request(selected.path, "PUT", selected.input),
      request(selected.path, "PUT", {
        ...selected.input,
        configuration: { ...configuration, maxFiles: 9 },
      }),
    ]);
    expect(results.map((response) => response.status).sort()).toEqual([200, 409]);
    const saved = BackendConfigurationView.parse(await (await request(selected.path)).json());
    expect(saved.revision).toBe(1);
  });

  it("T-AC-61 rejects foreign project/environment pairings without adopting configuration", async () => {
    const selected = await project();
    const other = await project("other-application");
    const path = `/projects/${other.project.id}/environments/${selected.environment.id}/backend`;
    expect((await request(path)).status).toBe(404);
    expect((await request(path, "PUT", selected.input)).status).toBe(404);
    expect(
      BackendConfigurationView.parse(await (await request(selected.path)).json()).configuration,
    ).toBeNull();
  });

  it.each(["authMaterial", "filesRoot", "databaseUrl", "runtimeConnected", "actor"])(
    "T-AC-61 rejects caller execution/material field %s",
    async (field) => {
      const selected = await project();
      const marker = `private-synthetic-${randomUUID()}`;
      const response = await request(selected.path, "PUT", { ...selected.input, [field]: marker });
      expect(response.status).toBe(422);
      expect(await response.text()).not.toContain(marker);
    },
  );

  it.each([
    { allowedOrigins: ["https://*.example.test"] },
    { allowedOrigins: ["https://example.test/path"] },
    { allowedOrigins: ["http://untrusted.example.test"] },
    { allowedOrigins: ["https://example.test", "https://example.test"] },
    { maxFileMiB: 33, storageMiB: 32 },
    { maxFiles: 0 },
    { eventRetention: Number.POSITIVE_INFINITY },
  ])("T-AC-61 rejects nonfinite or unsafe backend policy %j", (change) => {
    expect(BackendConfiguration.safeParse({ ...configuration, ...change }).success).toBe(false);
  });

  it("T-AC-55 derives active guard only from current actual controller configuration", async () => {
    const selected = await project();
    await request(selected.path, "PUT", selected.input);
    const guard = applicationLifecycleGuard(fixture.store, {
      projectId: selected.project.id,
      environmentId: selected.environment.id,
      configurationRevision: 1,
    });
    expect(await guard()).toMatchObject({ available: true });
    await fixture.store.db
      .update(schema.environments)
      .set({ recoveryHold: true })
      .where(eq(schema.environments.id, selected.environment.id));
    expect(await guard()).toMatchObject({ available: false });
    await fixture.store.db
      .update(schema.environments)
      .set({ recoveryHold: false })
      .where(eq(schema.environments.id, selected.environment.id));
    expect(await guard()).toMatchObject({ available: true });
    await fixture.store.db
      .update(schema.projects)
      .set({ status: "suspended" })
      .where(eq(schema.projects.id, selected.project.id));
    expect(await guard()).toMatchObject({ available: false });
  });

  it("T-AC-55 fences an old runtime after configuration is changed or disabled", async () => {
    const selected = await project();
    await request(selected.path, "PUT", selected.input);
    const guard = applicationLifecycleGuard(fixture.store, {
      projectId: selected.project.id,
      environmentId: selected.environment.id,
      configurationRevision: 1,
    });
    expect(await guard()).toMatchObject({ available: true });
    const changed = await request(selected.path, "PUT", {
      ...selected.input,
      expectedRevision: 1,
      configuration: { ...configuration, enabled: false },
    });
    expect(changed.status).toBe(200);
    expect(await guard()).toMatchObject({ available: false });
    expect(BackendConfigurationView.parse(await changed.json()).state).toBe("disabled");
  });

  it("T-AC-61 exposes the backend contract through the typed private owner client", async () => {
    const selected = await project();
    const client = createControlClient({
      baseUrl: `${fixture.origin}/api/v1`,
      headers,
      fetch: async (input, init) => fixture.app.request(new Request(input, init)),
    });
    expect(
      await client.backendConfiguration(selected.project.id, selected.environment.id),
    ).toMatchObject({ state: "unconfigured" });
    const saved = await client.configureBackend(
      selected.project.id,
      selected.environment.id,
      selected.input,
      randomUUID(),
    );
    expect(saved).toMatchObject({ state: "prepared", runtimeConnected: false, revision: 1 });
  });

  it("T-AC-61 refuses a desired file quota above its environment's declared disk budget", async () => {
    const selected = await project();
    const response = await request(selected.path, "PUT", {
      ...selected.input,
      configuration: { ...configuration, storageMiB: selected.environment.diskGiB * 1024 + 1 },
    });
    expect(response.status).toBe(409);
    expect(await response.json()).toMatchObject({ error: { code: "CAPACITY_EXCEEDED" } });
    expect(
      BackendConfigurationView.parse(await (await request(selected.path)).json()).revision,
    ).toBe(0);
  });

  it("T-AC-55 fences an expired preview even when an earlier database observation remains ready", async () => {
    const database = await databaseFixture();
    try {
      const actor = { ...database.freshOwner(), authenticatedAt: new Date().toISOString() };
      const updated = await database.core.createEnvironment(
        actor,
        database.project.id,
        {
          expectedProjectRevision: database.project.revision,
          name: "backend-preview",
          kind: "preview",
          expiresAt: new Date(Date.now() + 3600000).toISOString(),
          memoryMiB: 2048,
          cpuMilliCores: 1000,
          diskGiB: 20,
        },
        randomUUID(),
      );
      const preview = updated.environments.find(
        (environment) => environment.name === "backend-preview",
      );
      if (!preview) throw new Error("Preview fixture missing");
      await database.admit(preview.id);
      await database.infrastructure.foundation.tick("backend-preview-database-fixture");
      expect(
        (await database.core.getProject(actor, updated.id)).environments.find(
          (environment) => environment.id === preview.id,
        )?.status,
      ).toBe("ready");
      await database.core.configureBackend(
        actor,
        updated.id,
        preview.id,
        {
          expectedRevision: 0,
          expectedProjectRevision: updated.revision,
          expectedEnvironmentRevision: preview.revision,
          configuration,
        },
        randomUUID(),
      );
      const guard = applicationLifecycleGuard(database.store, {
        projectId: updated.id,
        environmentId: preview.id,
        configurationRevision: 1,
      });
      expect(await guard()).toMatchObject({ available: true });
      await database.store.db
        .update(schema.environments)
        .set({ expiresAt: new Date(Date.now() - 1000) })
        .where(eq(schema.environments.id, preview.id));
      expect(await guard()).toMatchObject({ available: false });
      expect((await database.core.backendConfiguration(actor, updated.id, preview.id)).state).toBe(
        "held",
      );
    } finally {
      await database.store.close();
    }
  });
});
